window.__finlexDocLoaded(10233,{"id":10233,"articles":[{"id":1000990,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Establishes capitalization of costs incurred to develop computer software to be sold, leased, or otherwise marketed (ASC 985-20) once 'technological feasibility' is established through general release.","seq":0},{"id":1000991,"no":"ASC 985-20","heading":"Technological Feasibility Window & Amortization","text":"• Capitalization Window (ASC 985-20-25): Expense all costs as R&D (ASC 730) until 'technological feasibility' (detailed program design or working model) is established; capitalize coding/testing costs until product is available for general release to customers.\n• Amortization & NRV Test (ASC 985-20-35): Amortize at the greater of revenue-ratio method or straight-line; evaluate unamortized cost against Net Realizable Value each balance sheet date.","seq":1},{"id":1000992,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Under US GAAP, software development has two distinct models (ASC 985-20 for external sale vs. ASC 350-40 for internal-use/SaaS); under IFRS, both sit under IAS 38's unified 6-criteria development model.","seq":2},{"id":1000993,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
